#include "exercise.h"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static bool positive(int x) { return x > 0; }
static bool bstring(const void *p) { return (*(const char *const *)p)[0] == 98; }
static void string_length(const void *p, void *out) {
    *(size_t *)out = strlen(*(const char *const *)p);
}
int main(void) {
    int c[] = {1, 5, 10, 25}, o[100];
    assert(find_fewest_coins(c, 4, 15, o) == 2 && o[0] == 5 && o[1] == 10);
    int d[] = {1, 4, 15, 20, 50};
    assert(find_fewest_coins(d, 5, 23, o) == 3);
    int e[] = {2, 4};
    assert(find_fewest_coins(e, 2, 3, o) == -1);
    assert(find_fewest_coins(c, 4, 0, o) == 0);
    assert(find_fewest_coins(c, 4, -1, o) == -1);
    {
        int values[] = {1, 5, 10, 25}, actual[100];
        assert(find_fewest_coins(values, 4, 1, actual) == 1);
        assert(actual[0] == 1);
    }
    {
        int values[] = {1, 5, 10, 25, 100}, actual[100];
        assert(find_fewest_coins(values, 5, 25, actual) == 1);
        assert(actual[0] == 25);
    }
    {
        int values[] = {1, 5, 10, 25, 100}, actual[100];
        assert(find_fewest_coins(values, 5, 15, actual) == 2);
        assert(actual[0] == 5);
        assert(actual[1] == 10);
    }
    {
        int values[] = {1, 4, 15, 20, 50}, actual[100];
        assert(find_fewest_coins(values, 5, 23, actual) == 3);
        assert(actual[0] == 4);
        assert(actual[1] == 4);
        assert(actual[2] == 15);
    }
    {
        int values[] = {1, 5, 10, 21, 25}, actual[100];
        assert(find_fewest_coins(values, 5, 63, actual) == 3);
        assert(actual[0] == 21);
        assert(actual[1] == 21);
        assert(actual[2] == 21);
    }
    {
        int values[] = {1, 2, 5, 10, 20, 50, 100}, actual[100];
        assert(find_fewest_coins(values, 7, 999, actual) == 15);
        assert(actual[0] == 2);
        assert(actual[1] == 2);
        assert(actual[2] == 5);
        assert(actual[3] == 20);
        assert(actual[4] == 20);
        assert(actual[5] == 50);
        assert(actual[6] == 100);
        assert(actual[7] == 100);
        assert(actual[8] == 100);
        assert(actual[9] == 100);
        assert(actual[10] == 100);
        assert(actual[11] == 100);
        assert(actual[12] == 100);
        assert(actual[13] == 100);
        assert(actual[14] == 100);
    }
    {
        int values[] = {2, 5, 10, 20, 50}, actual[100];
        assert(find_fewest_coins(values, 5, 21, actual) == 5);
        assert(actual[0] == 2);
        assert(actual[1] == 2);
        assert(actual[2] == 2);
        assert(actual[3] == 5);
        assert(actual[4] == 10);
    }
    {
        int values[] = {4, 5}, actual[100];
        assert(find_fewest_coins(values, 2, 27, actual) == 6);
        assert(actual[0] == 4);
        assert(actual[1] == 4);
        assert(actual[2] == 4);
        assert(actual[3] == 5);
        assert(actual[4] == 5);
        assert(actual[5] == 5);
    }
    {
        int values[] = {1, 10, 11}, actual[100];
        assert(find_fewest_coins(values, 3, 20, actual) == 2);
        assert(actual[0] == 10);
        assert(actual[1] == 10);
    }
    {
        int values[] = {1, 5, 10, 21, 25}, actual[100];
        assert(find_fewest_coins(values, 5, 0, actual) == 0);
    }
    return 0;
}
